    else:
        if supply >= 23:
            bid = 34.0
        elif supply >= 20:
            bid = 42.0
        elif supply >= 17:
            bid = 51.0
        else:
            bid = 61.0

        if max_prev > 0:
            if max_prev >= 120:
                bid = min(bid, 58.0)
            elif max_prev >= 90:
                bid = max(bid, 50.0)
            else:
                bid = max(bid, min(max_prev + 1.5, 68.0))

    if max_urgent > 0 and hp > 4 and no_water_days == 0:
        bid = min(bid, max_urgent - 6.0)

    if max_rich >= 120 and hp > 5 and supply >= 18:
        bid = min(bid, 55.0)

    if day >= 8:
        bid += 6.0
    if day >= 9:
        bid += 6.0

